pub fn screen(
  ctx: &Context,
  preset: Rc<Signal<usize>>,
  octave: Rc<Signal<i8>>,
  level: Rc<Signal<usize>>,
  selected: Rc<Signal<usize>>,
  values: Rc<Signal<Vec<Vec<usize>>>>,
) -> Result<Element, JsValue> {
  let screen = html! {
    div class="mt-[calc(var(--spacing-inset)_-_var(--spacing-bezel))] aspect-[var(--screen-aspect,2.39)] min-w-0 rounded-[12px] border-t-[1.5px] border-b-[1.5px] border-t-screen-edge border-b-screen-lip bg-screen p-[8px] shadow-screen" {
      div class="relative flex h-full items-center rounded-[4px] px-[20px] text-screen-ink" {
        div class="absolute top-[9px] right-[20px] left-[20px] flex items-baseline justify-between gap-[16px] font-screen text-[14px] leading-[18px] font-medium tracking-[0.08em] whitespace-nowrap text-screen-ink/60 first-letter:uppercase" {
          span class="min-w-0 truncate" { #{ |octave| octave_label(*octave.get()) } }
          span class="shrink-0" {
            span class="text-synth-red" { #{ |level| format!("Level {}%", *level.get() * 10) } }
          }
        }
        div class="h-[160px] w-full text-screen-ink" {}
        div class="absolute right-[20px] bottom-[9px] left-[20px] flex items-baseline justify-between gap-[16px] font-screen text-[12px] leading-[15px] font-medium tracking-[0.08em] whitespace-nowrap text-screen-ink/60 first-letter:uppercase" {
          span class="min-w-0 truncate" {
            span { #{ |preset| PRESETS[*preset.get()].name } }
            #{ |values, preset| if unsaved(*preset.get(), &values.get()) { unsaved_mark() } else { String::new() } }
            #{ |preset| format!("&nbsp;&nbsp;{}", PRESETS[*preset.get()].engine) }
          }
          span class="shrink-0" {
            span class="text-synth-green" { #{ |preset, selected| PRESETS[*preset.get()].params[*selected.get()].name } }
            " "
            span class="text-synth-blue" {
              #{ |preset, selected, values| {
                let (preset, selected) = (*preset.get(), *selected.get());
                PRESETS[preset].params[selected].values[values.get()[preset][selected]]
              } }
            }
          }
        }
      }
    }
  };
  Ok(screen)
}

pub fn overlay(
  ctx: &Context,
  overlay: Rc<Signal<Option<(&'static str, usize)>>>,
) -> Result<Element, JsValue> {
  let element = html! {
    div class=#{ |overlay| if overlay.get().is_some() { OVERLAY } else { "hidden" } } {
      div class="flex w-[62%] flex-col gap-[10px] rounded-[10px] border border-screen-ink/18 bg-screen/92 px-[18px] pt-[14px] pb-[16px]" {
        div class="flex justify-between font-screen text-[14px] leading-[18px] font-semibold tracking-[0.08em] first-letter:uppercase" {
          #{ |overlay| overlay.get().map_or("", |(label, _)| label) }
          #{ |overlay| overlay.get().map_or(String::new(), |(_, step)| format!("{}%", step * 10)) }
        }
        div class="relative h-[12px] overflow-hidden rounded-[3px] bg-screen-ink/12" {
          div
          class="h-full bg-screen-ink transition-[width] duration-160 ease-[ease-out]"
          style=#{ |overlay| &format!("width: {}%", overlay.get().map_or(0, |(_, step)| step * 100 / (KNOB_STEPS - 1))) }
          {}
        }
      }
    }
  };
  Ok(element)
}

pub fn corner(
  ctx: &Context,
  on_theme: Rc<Device>,
  theme: Rc<Signal<Theme>>,
  system_dark: Rc<Signal<bool>>,
) -> Result<Element, JsValue> {
  let midi = html! { button class={ CORNER_BUTTON } { span class={ ICON } {} } };
  let toggle = html! {
    button
    class={ CORNER_BUTTON }
    @click={ move |_| on_theme.cycle_theme() }
    {
      span class={ ICON } {
        #{ |theme, system_dark| match theme.get().next(*system_dark.get()) {
          Theme::Light => SUN,
          _ => MOON,
        } }
      }
    }
  };
  Ok(toggle)
}

pub fn knob(style: String) -> Result<Element, JsValue> {
  let element = html! {
    button
    class="group relative inline-flex size-(--size) cursor-ew-resize touch-none items-center justify-center rounded-[50%] drop-shadow-knob select-none [--size:var(--knob-size,68px)] focus-visible:outline-3 focus-visible:outline-offset-3 focus-visible:outline-[#2f7de1] focus-visible:outline-solid"
    style={ &style }
    {}
  };
  Ok(element)
}

#[allow(clippy::too_many_arguments)]
pub fn pad(
  ctx: &Context,
  index: usize,
  spec: &'static Pad,
  is_shift: bool,
  legend: &'static str,
  style: String,
  held_pads: Rc<Signal<BTreeSet<usize>>>,
  shift_key: Rc<Signal<bool>>,
  latched: Rc<Signal<bool>>,
  chord_key: Rc<Signal<Option<usize>>>,
  latched_chord: Rc<Signal<Option<usize>>>,
  preset: Rc<Signal<usize>>,
) -> Result<Element, JsValue> {
  let element = html! {
    button
    class=#{ |held_pads, shift_key, latched, chord_key, latched_chord| {
      let held = held_pads.get().contains(&index) || (is_shift && (*shift_key.get() || *latched.get()));
      let active = chord_key.get().or(*latched_chord.get());
      let lit = matches!(spec.job, Job::Chord(chord) if active == Some(chord));
      match (lit, held) {
        (true, true) => PAD_LIT_HELD,
        (true, false) => PAD_LIT,
        (false, true) => PAD_HELD,
        (false, false) => PAD,
      }
    } }
    style={ &style }
    {
      kbd class={ HOTKEY } { { legend } }
      span class={ FACE } {}
    }
  };
  let led = html! {
    span class=#{ |preset| if spec.job == Job::Preset(*preset.get()) { LED_ON } else { LED } } {}
  };
  Ok(element)
}

pub fn key(
  ctx: &Context,
  semitone: u8,
  style: &'static KeyStyle,
  slot: String,
  legend: String,
  held: Rc<Signal<BTreeMap<u8, Vec<(u8, u8)>>>>,
  preset: Rc<Signal<usize>>,
  octave: Rc<Signal<i8>>,
) -> Result<Element, JsValue> {
  let key = html! {
    button
    class=#{ |held| {
      let lit = held.get().values().flatten().any(|&(lit, _)| lit == semitone);
      if lit { style.lit } else { style.rest }
    } }
    style={ &slot }
    {
      span class={ style.labels } {
        kbd class={ style.hotkey } { { &legend } }
        span class={ style.note } {
          #{ |preset, octave| match PRESETS[*preset.get()].pieces {
            Some(pieces) => pieces[semitone as usize].face.to_string(),
            None => notes::engraved(notes::midi(semitone, *octave.get())),
          } }
        }
      }
    }
  };
  Ok(key)
}
